DO $migrare$
DECLARE v_amprenta text; v_scrisa text; v_inainte text; v_comentariu text;
  v_lipsa text[]; v_impl text[]; v_porti text; v_porti_e3 text; v_porti_e3b text;
BEGIN
  IF current_user <> 'postgres' OR current_setting('gazpet.livrare_migrare',true)
      IS DISTINCT FROM '20261109a_izometrie_e4a_flux:' || txid_current() THEN
    RAISE EXCEPTION 'E4a: numai postgres prin runner'; END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN RAISE EXCEPTION 'E4a: READ COMMITTED'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('gazpet.livrare_migrare'));
  IF to_regclass('public.izo_tronson_config') IS NOT NULL OR EXISTS
    (SELECT 1 FROM pg_roles WHERE rolname='izo_montaj_writer') THEN RAISE EXCEPTION 'E4a exista deja'; END IF;
  LOCK TABLE public.izo_proiect_config,public.executie_tronsoane,public.executie_pachete_lansare,
    public.executie_tevi,public.executie_pachete_documente IN ACCESS EXCLUSIVE MODE;
  @@PRE_MD5@@
  v_lipsa := public.fn_izo_porti_lipsa() || public.fn_izo_porti_e3_lipsa();
  IF cardinality(v_lipsa) <> 0 THEN RAISE EXCEPTION 'E4a baseline: %',v_lipsa; END IF;
  @@IMPL_PRE@@
  @@AMPRENTA@@
  v_comentariu := obj_description('public.magazie_bucati_evenimente'::regclass,'pg_class');
  IF v_amprenta IS DISTINCT FROM substring(v_comentariu FROM 'amprenta=([0-9a-f]{32})') THEN
    RAISE EXCEPTION 'E4a amprenta baseline'; END IF;
  v_inainte := v_amprenta;
  v_porti := obj_description('public.fn_izo_porti_definitii()'::regprocedure,'pg_proc');
  v_porti_e3 := obj_description('public.fn_izo_porti_e3_definitii()'::regprocedure,'pg_proc');
  v_porti_e3b := obj_description('public.fn_izo_porti_e3b_definitii()'::regprocedure,'pg_proc');

  CREATE ROLE izo_montaj_writer NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  GRANT izo_montaj_writer TO postgres WITH INHERIT FALSE, SET TRUE;
  GRANT USAGE ON SCHEMA public TO izo_montaj_writer;
  CREATE TABLE public.izo_tronson_config (
