    proiect_id bigint NOT NULL REFERENCES public.executie_proiecte(id) ON DELETE RESTRICT,
    flux_montaj boolean NOT NULL DEFAULT false, flux_de_la timestamptz,
    flux_motiv text, flux_schimbat_de text,
    sens_numerotare text NOT NULL DEFAULT 'crescator' CHECK (sens_numerotare IN ('crescator','descrescator')),
    nr_sudura_start integer CHECK (nr_sudura_start > 0),
    perete_proiectat jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(perete_proiectat)='array'),
    executant_implicit text NOT NULL DEFAULT 'Gazpet',
    server_ver bigint NOT NULL DEFAULT nextval('public.izo_server_ver_seq'),
